class Solution {
public:
    bool makePalindrome(std::string s) {
        int mismatches = 0;
        int left = 0, right = (int)s.size() - 1;
        while (left < right) {
            if (s[left] != s[right]) {
                mismatches++;
                if (mismatches > 2) return false;
            }
            left++;
            right--;
        }
        return true;
    }
};

class Solution {
    public boolean makePalindrome(String s) {
        int mismatches = 0;
        int left = 0, right = s.length() - 1;
        while (left < right) {
            if (s.charAt(left) != s.charAt(right)) {
                mismatches++;
                if (mismatches > 2) return false;
            }
            left++;
            right--;
        }
        return true;
    }
}

var makePalindrome = function(s) {
    let mismatches = 0;
    let left = 0, right = s.length - 1;
    while (left < right) {
        if (s[left] !== s[right]) {
            mismatches++;
            if (mismatches > 2) return false;
        }
        left++;
        right--;
    }
    return true;
};
